"""Real browser WebAuthn, denial/revocation events and product audit details; Google emulated."""
import importlib.util,json,unittest
from pathlib import Path
from urllib.parse import urlsplit
from playwright.sync_api import expect
spec=importlib.util.spec_from_file_location('audit_qa',Path(__file__).with_name('test-audit.py'));qa=importlib.util.module_from_spec(spec);spec.loader.exec_module(qa)
ROOT,ORIGIN=qa.ROOT,qa.ORIGIN
class SecurityAudit(qa.Audit):
    def setUp(self):
        super().setUp();self.lose_logout=False
    def relay(self,route):
        req=route.request;path=urlsplit(req.url).path
        if path=='/api/v1/session/logout' and self.lose_logout:
            self.lose_logout=False;headers={k:v for k,v in req.all_headers().items() if k not in ['host','content-length']};self.local(path,body=req.post_data_buffer,headers=headers,method=req.method);route.abort();return
        super().relay(route)
    def events(self,action):return [e for e in self.local('/test/security-events')['events'] if e['action']==action]
    def audit_page(self):
        self.local('/test/enable-audit',{});self.page.goto(ORIGIN+'/auditoria-dev.html');expect(self.page.locator('#audit')).to_be_visible()
    def login(self):
        self.begin_login();expect(self.page.locator('#passkey')).to_be_visible();self.page.locator('#passkey-button').click();expect(self.page.locator('#complete')).to_be_visible()
    def test_security_mobile_known_unknown_wrong_pin_anonymous_audit_and_successful_login(self):
        self.activate();self.logout();self.begin_login('0193');expect(self.page.locator('#status')).to_contain_text('Não foi possível entrar com os dados informados');self.page.locator('#login-email').fill('unknown@example.invalid');self.page.locator('#login-pin').fill('8274');self.page.get_by_role('button',name='Entrar na minha conta',exact=True).first.click();expect(self.page.locator('#status')).to_contain_text('Não foi possível entrar com os dados informados');expect(self.page.get_by_role('button',name='Entrar na minha conta',exact=True).first).to_be_enabled();self.assertEqual(len(self.events('IDENTITY_ACCESS_DENIED')),2);self.login();self.audit_page();self.page.locator('#operation').select_option('IDENTITY_ACCESS_DENIED');self.apply();expect(self.page.locator('.audit-record')).to_have_count(2);expect(self.page.locator('.audit-record').first).to_contain_text('Sistema de autenticação');expect(self.page.locator('.audit-record').first).to_contain_text('Autenticação');self.page.locator('.audit-record button').first.click();expect(self.page.locator('#detail-content')).to_contain_text('Credenciais não confirmadas');self.assertNotIn('unknown@example.invalid',self.page.content());self.assertNotIn('0193',self.page.content());self.page.locator('#close-detail').click();self.assertTrue(self.page.evaluate('document.documentElement.scrollWidth<=innerWidth'));target=ROOT/'work/qa-security-events';target.mkdir(parents=True,exist_ok=True);self.page.screenshot(path=str(target/'acessos-negados-celular.png'),full_page=True);self.assertEqual(self.errors,[])
    def test_security_invalid_passkey_signature_is_denied_without_new_session_or_identity_attribution(self):
        self.activate();self.logout();self.begin_login();expect(self.page.locator('#passkey')).to_be_visible();self.corrupt_signature=True;self.page.locator('#passkey-button').click();expect(self.page.locator('#status')).to_contain_text('Não foi possível entrar com os dados informados');expect(self.page.locator('#passkey-button')).to_be_enabled();denied=self.events('IDENTITY_ACCESS_DENIED');self.assertEqual(len(denied),1);self.assertEqual(denied[0]['actor'],'SYSTEM_AUTH');self.assertEqual(denied[0]['detail']['code'],'PASSKEY_REJECTED');self.assertEqual(self.local('/test/checkout-state')['sales'],0);self.assertFalse(any(c['name']=='__Host-livraria_session' for c in self.context.cookies()));self.assertEqual(self.errors,[])
    def test_security_lost_logout_ack_retries_original_cookie_and_revocation_is_logged_once(self):
        self.activate();self.lose_logout=True;self.page.locator('#logout-button').click();expect(self.page.locator('#status')).to_contain_text('Não foi possível concluir agora');expect(self.page.locator('#logout-button')).to_be_enabled();self.assertEqual(len(self.events('IDENTITY_LOGOUT')),1);self.page.locator('#logout-button').click();expect(self.page.locator('#initial')).to_be_visible();self.assertEqual(len(self.events('IDENTITY_LOGOUT')),1);self.login();self.assertEqual(len(self.events('IDENTITY_LOGOUT')),1);self.assertEqual(self.errors,[])
    def test_security_account_menu_recovers_lost_logout_by_recognizing_revoked_session(self):
        self.activate();self.local('/test/enable-profile',{});self.audit_page();expect(self.page.locator('.account-menu')).to_be_visible();self.page.locator('.account-menu summary').click();self.lose_logout=True;self.page.get_by_role('button',name='Sair',exact=True).click();expect(self.page.get_by_role('button',name='Tentar sair novamente',exact=True)).to_be_enabled();self.assertEqual(len(self.events('IDENTITY_LOGOUT')),1);self.page.get_by_role('button',name='Tentar sair novamente',exact=True).click();expect(self.page).to_have_url(ORIGIN+'/acesso-dev.html');expect(self.page.locator('#initial')).to_be_visible();self.assertEqual(len(self.events('IDENTITY_LOGOUT')),1);self.assertEqual(self.errors,[])
    def test_security_shared_budget_blocks_once_and_repeated_request_keeps_single_transition(self):
        self.activate();self.logout()
        for i in range(5):
            self.begin_login('0193');expect(self.page.get_by_role('button',name='Entrar na minha conta',exact=True).first).to_be_enabled()
        expect(self.page.locator('#status')).to_contain_text('várias tentativas');self.assertEqual(len(self.events('IDENTITY_AUTH_BLOCKED')),1);self.begin_login('0193');expect(self.page.get_by_role('button',name='Entrar na minha conta',exact=True).first).to_be_enabled();self.assertEqual(len(self.events('IDENTITY_AUTH_BLOCKED')),1);self.assertEqual(len(self.events('IDENTITY_ACCESS_DENIED')),4);self.assertEqual(self.errors,[])
    def test_security_product_edit_actual_metadata_and_admin_deactivation_are_visible_in_audit(self):
        self.activate();self.catalog();self.create(title='Edição original');self.save();expect(self.page.locator('.book')).to_have_count(1);self.page.get_by_role('button',name='Detalhes e edição',exact=True).click();expect(self.page.locator('#editor')).to_be_visible();self.page.locator('#title').fill('Edição revisada');self.page.locator('#author').fill('Autor revisado');self.page.locator('#edition').fill('2ª');self.page.locator('#price').fill('45,00');self.save();expect(self.page.locator('.book')).to_contain_text('Edição revisada');self.audit_page();self.page.locator('#operation').select_option('PRODUCT_UPDATE');self.apply();expect(self.page.locator('.audit-record')).to_have_count(1);self.page.locator('.audit-record button').click();expect(self.page.locator('#detail-content')).to_contain_text('Edição original');expect(self.page.locator('#detail-content')).to_contain_text('Edição revisada');expect(self.page.locator('#detail-content')).to_contain_text('R$ 45,00');expect(self.page.locator('#detail-content')).to_contain_text('2ª');self.page.locator('#close-detail').click();self.catalog();self.page.once('dialog',lambda dialog:dialog.accept());self.page.get_by_role('button',name='Excluir livro',exact=True).click();expect(self.page.locator('.book')).to_have_count(0);self.audit_page();self.page.locator('#operation').select_option('PRODUCT_UPDATE');self.apply();expect(self.page.locator('.audit-record')).to_have_count(2);self.page.locator('.audit-record button').first.click();expect(self.page.locator('#detail')).to_be_visible();self.assertEqual(self.page.locator('.changes').last.locator('dt').filter(has_text='Ativo').evaluate('(el)=>el.nextElementSibling.textContent'),'Não');self.assertEqual(self.errors,[])
if __name__=='__main__':
    suite=unittest.TestSuite(SecurityAudit(name) for name in unittest.defaultTestLoader.getTestCaseNames(SecurityAudit) if name.startswith('test_security_'))
    result=unittest.TextTestRunner(verbosity=2).run(suite);raise SystemExit(0 if result.wasSuccessful() else 1)
